import java.util.*; class Playlist07{private final String[]songs;private int count;Playlist07(int n){songs=new String[Math.max(0,n)];}boolean addSong(String s){if(count==songs.length||s==null)return false;songs[count++]=s;return true;}String[]getSongs(){return Arrays.copyOf(songs,count);}int getCount(){return count;}} public class Week07Problem02{public static void main(String[]z){Playlist07 p=new Playlist07(3);p.addSong("Song A");p.addSong("Song B");String[]a=p.getSongs();a[0]="Changed";System.out.println(Arrays.toString(p.getSongs()));System.out.println("Count: "+p.getCount());}}